head.script:
scwin.screenId = "jldstf07302";

///////// 1. 변수 및 선언 영역 /////////

scwin.vBzProcsNo = "";

scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";

scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";

scwin.MGS_NO_UPDT = "저장할 수정내용이 없습니다.";

scwin.contnId = undefined;

scwin.file_flag = "N";

scwin.vScrenID = "ULDSTF07302.gfm";


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        const arr = new Array();
        const parentWin = $c.frame.Provider("../");
        fn_GetPar = parentWin.fn_GetPar;
        fn_SetPar = parentWin.fn_SetPar;
        if (fn_GetPar != null) {
            fn_GetPar(arr);
        }
        $c.util.getComponent("ipt_txb_IsurCd").setValue((arr.length >= 1 ? arr[0] : ""));
        $c.util.getComponent("ipt_txb_CoNm").setValue((arr.length >= 3 ? arr[2] : ""));
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        await scwin.searchWebRflct();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07302.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts_ReqInf = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_ReqInf')) : $c.util.getComponent('dts_ReqInf');

scwin.dts_Cmt = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Cmt')) : $c.util.getComponent('dts_Cmt');

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @description txb_IsurCd 을(를) 값을 넣는다 · txb_CoNm 을(를) 값을 넣는다 외
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf07302.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name scwin.dts_Cmt_onloadcompleted
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowcount
 * @returns
 * @hidden N
*/
scwin.dts_Cmt_onloadcompleted = async function (rowcount) {
    /* sdd-asis-lifecycle:begin dts_Cmt_onloadcompleted — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (scwin.dts_Cmt.CountRow > 0) {
        fn_setKeyCtrOnUpd();
        fn_searchReqInf();
        fn_read();
    } else {
        if (await $c.win.confirm(MSG_NO_COMT)) {
            fn_addNewCmt();
        } else {
            $c.frame.CloseFrame();
        }
    }
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.dts_Cmt_onrowposchanged
 * @author Inswave
 * @date 2026. 09. 29
 * @param row
 * @returns
 * @hidden N
*/
scwin.dts_Cmt_onrowposchanged = function (row) {
    /* sdd-asis-lifecycle:begin dts_Cmt_onrowposchanged — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (scwin.dts_Cmt.CountRow > 0) {
        if (scwin.dts_Cmt.getCellData(row, "BZ_PROCS_NO") !== "") {
            fn_searchReqInf();
        }
        fn_read();
    }
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.dts_ReqInf_onloadcompleted
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowcount
 * @returns
 * @hidden N
*/
scwin.dts_ReqInf_onloadcompleted = function (rowcount) {
    /* sdd-asis-lifecycle:begin dts_ReqInf_onloadcompleted — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_med_LIST_DELIB_SCHDL_DD').setSelectionValue(0, 8, scwin.dts_ReqInf.getCellData(1, "LIST_DELIB_SCHDL_DD"));
    $c.util.getComponent('ipt_med_INVSTG_DTL_WEB_DP_DD').setSelectionValue(0, 8, scwin.dts_ReqInf.getCellData(1, "INVSTG_DTL_WEB_DP_DD"));
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.tr_Save_onfail
 * @author Inswave
 * @date 2026. 09. 29
 * @description 알림을 띄운다
 * @param
 * @returns
 * @hidden N
*/
scwin.tr_Save_onfail = async function () {
    /* sdd-asis-lifecycle:begin tr_Save_onfail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await $c.win.alert(scwin.MSG_TR_FAIL);
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.tr_Save_onsuccess
 * @author Inswave
 * @date 2026. 09. 29
 * @description 알림을 띄운다 외
 * @param
 * @returns
 * @hidden N
*/
scwin.tr_Save_onsuccess = async function () {
    /* sdd-asis-lifecycle:begin tr_Save_onsuccess — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await $c.win.alert(scwin.MSG_TR_DOME);
    scwin.parentRefresh();
    $c.frame.CloseFrame();
    /* sdd-asis-lifecycle:end */
};

/**
 * @event
 * @name scwin.btn_Close_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Close_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin btn_Close_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.frame.CloseFrame();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07302.btn_Close_onclick' }); }
};

/**
 * @event
 * @name scwin.img_Save_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.img_Save_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin img_Save_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.fn_save("I");
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07302.img_Save_onclick' }); }
};

/**
 * @event
 * @name scwin.img_SetInvstgDtlWebDpDd_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.img_SetInvstgDtlWebDpDd_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin img_SetInvstgDtlWebDpDd_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.showCalendar(ipt_med_INVSTG_DTL_WEB_DP_DD);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07302.img_SetInvstgDtlWebDpDd_onclick' }); }
};

/**
 * @event
 * @name scwin.img_SetListDelibSchdlDd_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.img_SetListDelibSchdlDd_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin img_SetListDelibSchdlDd_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.showCalendar(ipt_med_LIST_DELIB_SCHDL_DD);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07302.img_SetListDelibSchdlDd_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_script_dts_ReqInf
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_script_dts_ReqInf = async function () {
    $c.util.getComponent("dma_scriptDts_ReqInfReq").set("SCREN_ID", "ULDSTF07302.gfm");
    $c.util.getComponent("dma_scriptDts_ReqInfReq").set("BZ_PROCS_NO", "");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD", unresolved: "query_param:SCREN_PROCES_TP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_ReqInf",
        method: "post",
        action: "/konex/PrelmInvstgKonex.do",
        ref: "dma_scriptDts_ReqInfReq",
        target: "dts_ReqInf=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_ReqInf_onloaderror'] === 'function') ? scwin['dts_ReqInf_onloaderror'] : (typeof scwin['dts_ReqInf_onfail'] === 'function') ? scwin['dts_ReqInf_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_ReqInf_onloadcompleted'] === 'function') ? scwin['dts_ReqInf_onloadcompleted'] : ((typeof scwin['dts_ReqInf_onsuccess'] === 'function') ? scwin['dts_ReqInf_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_ReqInf'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07302.tx_script_dts_ReqInf" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.sbm_tr_Save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.sbm_tr_Save = async function () {
    const sbmOptions = {
        id: "sbm_tr_Save",
        method: "post",
        action: "/konex/PrelmInvstgKonex.do",
        ref: "dma_sbmTr_SaveReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07302.sbm_tr_Save" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.showCalendar
 * @author Inswave
 * @date 2026. 09. 29
 * @param o
 * @returns
 * @hidden N
*/
scwin.showCalendar = function (o) {
    /* sdd-asis-lifecycle:begin fn_ShowCalendar — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ((o != null) && (!o.readOnly)) {
        popUpCalendar2(o);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getUserId
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getUserId = function () {
    /* sdd-asis-lifecycle:begin fn_getUserId — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    return $c.session.getUserInfo("empNo");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchWebRflct
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchWebRflct = async function () {
    /* sdd-asis-lifecycle:begin fn_searchWebRflct — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let uri = "/konex/PrelmInvstgKonex.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + $c.fil.SCREN_PROCS_TP_CD_01 + "&method=readWebRflct";
    uri += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;

    await scwin.tx_script_dts_ReqInf();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.parentRefresh
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.parentRefresh = function () {
    /* sdd-asis-lifecycle:begin parentRefresh — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fr_fn_list_sync = $c.frame.Provider("../").fn_list_sync;
    fr_fn_list_sync();
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
scwin.fn_save = scwin.sbm_tr_Save;
